class WeightedPicker {
  private prefix: number[] = [];
  private total = 0;

  constructor(weights: number[]) {
    for (const w of weights) this.prefix.push(this.total += w);
  }

  pick(): number {
    // integer target in [1, total]; the answer is the first prefix sum >= target
    const target = Math.floor(Math.random() * this.total) + 1;
    let lo = 0, hi = this.prefix.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.prefix[mid] < target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}

